WITH eligible AS (SELECT s.* FROM customers s WHERE EXISTS (SELECT 1 FROM sessions c WHERE c.customer_id = s.id AND c.browser = 'Safari')) SELECT DATE_TRUNC('WEEK', signup_date) AS week_start, DATE_TRUNC('YEAR', signup_date) AS year_start, SUM(age) FILTER (WHERE segment = 'Corporate') AS corporate_total_age, SUM(CASE WHEN country = 'UK' THEN age ELSE 0 END) AS uk_age, CORR(credit_limit, age) AS corr_credit_limit_age, COUNT(*) AS num_rows FROM eligible GROUP BY DATE_TRUNC('WEEK', signup_date), DATE_TRUNC('YEAR', signup_date) HAVING SUM(age) FILTER (WHERE segment = 'Corporate') < 1000000
